entrypoint:
import type { ForgeClient } from '@tryforge/forgescript';
import hello from './commands/hello';
import helloSlash from './slash/hello';

export function register(client: ForgeClient) {
  client.commands.add(hello);
  client.applicationCommands.add(helloSlash);
}

prefix:
import { BaseCommand } from '@tryforge/forgescript';

export default new BaseCommand({
  name: 'hello',
  type: 'messageCreate',
  code: `$sendMessage[Hello from an extra!]`,
});

slash:
import { ApplicationCommand } from '@tryforge/forgescript';

export default new ApplicationCommand({
  data: {
    name: 'extra-hello',
    description: 'Say hello from an extra',
    type: 1,
  },
  code: `$interactionReply[Hello from an extra!]`,
});
